        "横イルカ H（[4]6H）：長距離の突進中段。ガードさせると相手がやや有利。→ 6Pで迎撃するのが最優先。ガードしてしまったら反撃せず、メイの次の近Sや投げに備える（投げ抜け仕込み）。",
        "縦イルカ（[2]8S/H）：上に飛んでから落ちる。→ 6P/2Hで落とす。ガードした場合は着地後に近S/2K始動で確反。",
        "オーバーヘッドキッス（623K）：前方に飛びついてから掴むコマンド投げ。発生がやや遅いが、投げ抜け不可。→ 密着でメイが前に飛びついたらジャンプかバクステ。打撃を1回ガードした後の投げに警戒。",
        "有栖川スパークル（214P）：発生の遅いボール。固めと起き攻めに使われる。→ 遠距離では前ジャンプで越える。固めで出された場合はガードして相手の次の動きを見る。",
