        "相手を壁に追い込んだ時：メイの切り返しは6Pとグレート山田アタック（50%ゲージ）。固め中に隙間を作らず、投げを混ぜる。ゲージ50%以上の時は固めに必殺技キャンセル可能な技を使い、覚醒必殺技に対してガードできるようにする。山田をガードしたら最大確反→壁割り。",
