        "密着でアクセルの打撃をガードした後に立ちガードを続けない（冬蟷螂は投げ抜け不可。ジャンプで拒否）。",
        "ゲージ50%以上のアクセルの前で中距離の技を空振りしない（百重鎌焼で差し返される）。"
