        "バッドムーン（j.236P、空中から回転しながら落ちる中段）はガード後にミリアが不利なので、ガードしたら近S/2K始動で確反。ターボフォール（j.236K、急降下）は空中からの軌道変化で、着地後に投げや下段が来る。ターボフォールを見たら着地に6Pか投げ抜け仕込み。",
