        "ダウロ（623P・飛び上がり突き）はラムの対空兼リバーサル。ジャンプ攻撃を重ねる時に食らう。空中からの接近は着地を散らす。",
        "エラルルーモ（214P→P→P）は3段の連続攻撃、3段目で浮かせる。1段目をガードした後に2段目・3段目を出すかどうかで止めることができる。ガード後は相手の派生を待たず、1段目ガード後に6Pか無敵技で割り込める。",
