        "6H密着ガード → 近S始動。",
        "2D近距離ガード → 2K始動。",
        "エラルルーモ3段目（214P×3）ガード → 近S始動。",
        "バジョネート（236S/H）を見てから前ジャンプ → 剣を飛び越えて着地にJSからコンボ、または着地に近S。剣が投げられた側の技が短くなっているので安全に触れる。"
