        "相手を壁に追い込んだ時：レオの切り返しはアイゼンシュトゥルム（無敵対空）と覚醒必殺技。地上で打撃を重ねて空中からの重ねを控える。アイゼンシュトゥルムを詐欺飛びで釣ってガードし確反。",
