        "相手を壁に追い込んだ時：名残雪の切り返しは垂雪（無敵対空）と忘れ雪（覚醒）。地上で打撃を重ね、空中からの重ねは控える。垂雪を詐欺飛びで釣ってガードし確反。血のゲージが高い時は垂雪が出せないので、強気に攻める。",
