        "ジオのダッシュは速い。ダッシュ近Sや2Kで触りに来る。ダッシュを見たら2Pや2Kを置いて先に触る、または6Pでダッシュ近Sを潰す。",
        "トロヴァン（236K・前進する蹴り）は中距離からの接近技。ガードさせて相手有利気味で、ガード後に近Sや投げが来る。→ 見てからガードし、ガード後は投げ抜けを押しながらガード。",
