        "中距離：闇慈の遠S（扇で横に長い、発生速め）、5H（大きく振る、発生遅め）、6H（長いリーチの斬り、発生遅め）が主力。遠Sは6Pで潰せる。5Hと6Hは発生が遅いので見てからダッシュで潰す。",
        "風神（236H・跳ねて前進する斬り）は中距離からの接近技。ガードさせて闇慈有利で、派生に移行する。→ 見てからガードし、派生を見る。S派生（凪刃）は下段、H派生（臨）は中段気味の浮かせ、K派生（一足飛び）はジャンプで裏に回る、P派生（疾）は蝶を出して固め直し。",
        "風神を飛び越えると一足飛びで着地に回られる。風神をジャンプで避けず、ガードして派生を見分けるのが基本。風神の発生前に6Pを置けば潰せることがある。",
        "水月（236K・回避）は打撃を無効化して反撃する回避技。中距離で打撃を置き続けると取られる。水月の硬直は長いので、水月を見たら投げか下段（水月は下段を取れない）。",
        "紅（623H・無敵対空）は闇慈のリバーサル兼対空。空中からの重ねは控える。ガードしたら着地に確反。",
        "花鳥風月改（覚醒・当て身）は覚醒ゲージ50%の当て身。打撃を取って高火力。覚醒ゲージがある闇慈に打撃を重ね続けない。投げと下段を混ぜる。",
        "対空：闇慈の6Pと2H（扇で上を払う）が対空。空中ダッシュで接近すると2Hで落とされる。闇慈のジャンプは浮遊気味で長い。JSとJHで飛び込む。6Pで落とす。"
