        "風神の派生を見分ける：Sは地面を払う下段、Hは斬り上げる中段気味、Kはジャンプ、Pは蝶。しゃがみガードを基準にして、Hの斬り上げが見えたら立つ。Kは着地点でガード方向を逆に。",
