        "開幕6Pは遠Sを潰すが、ベヘモットタイフーンには負けることがある（ベヘモットは範囲が大きい）。開幕バクステはベヘモットを空振りさせて硬直に確反。",
        "ゴールドルイスの開幕バクステ→スカイフィッシュ（236S・機関銃）はセキュリティレベルを上げる。スカイフィッシュを見たらジャンプで越えて着地に殴る。"
