        "中距離：ゴールドルイスの遠S（横に長い）、5H（巨大な振り、発生遅め）、2D（長いスライディング、下段、速い）、6H（大きく振る、発生遅め）、ベヘモットタイフーン（半回転＋H、8方向、巨大な範囲）が主力。遠Sは6Pで潰す。5Hと6Hは発生が遅いので見てからダッシュで潰す。2Dは低姿勢で6Pが空振りするので、2Kや足払いで先に触る。",
