        "暴れ所：サーヴァントが攻撃に行っていない時の遠S/2S後。本体単体の遠Sと2Sの後は相手が大きく有利ではないので、2P/5P/2Kで割り込みが通る。サーヴァントの攻撃をガードした直後は暴れない（本体の技が重なっている）。",
        "FDの使い所：近S/遠Sのところで押して遠Sの間合いから外す。サーヴァントとの2方向攻撃が始まる前に距離を取るのが目的。サーヴァントが自分の背後にいる時はFDで前に下がれないので、先にジャンプで逃げる。",
