        "214S（構え、ステディエイム）：構え中は相手が集中ゲージを消費し続け、Hで狙い撃ち。構えの弾は空中にも当たるので『構えを見たらジャンプしない』。構えは集中ゲージをかなり食うので、ガードで歩き続ければ相手は集中（214P）かリロードを挟む必要が出てくる。その硬直に走る。",
        "中距離（2Sが届く距離）：相手の2S（長い前方牽制）、遠S、5K、6Pが主力。2Sは先端が強いが硬直は普通で、空振りを見たらダッシュ近Sで差し返せる。この距離では自分の技を置かず、2Sの空振りを待ってダッシュで入る。",
        "呪い（236P）：ゆっくり飛ぶ球。当たると一定時間、相手の弾が自動で自分を狙う。ジャンプで避ける。呪いが付いたらその間は弾の圧力が上がるので、無理に歩かず近くに来た時だけ殴る。",
