        "密着：ケイオスの近S・2K・5Pは普通で、密着での切り返しは覚醒必殺技に頼る。密着で殴り合えば勝てるので、触ったら絶対に離れない。相手は離れるためにバクステ→銃抜きをするので、起き攻めは遅らせ打撃とダッシュ投げを中心に。",
        "飛び込み：弾を避けるために飛ぶのはいいが、214Sの構えとj.Hがあるので『高く飛んで近づく』より『低空ダッシュで一気に距離を詰める』方が安全。",
        "弾数の管理：相手が5発撃った時点で前に出る。6発目を撃ったら22Pリロードか集中（214P）をする必要があり、そこが唯一安全に近づける時間。"
