        "優先順位：まず弾の重ねをしゃがみガード。弾後の近Sに暴れず、近Sガード後の投げに4Hで投げ抜け入れ込み。相手がバクステで離れたら即前ダッシュ（起き攻めを放棄した瞬間が一番安全に近づける）。",
