        "自分の選択肢：開幕バクステ（畳と5Kをすかしてから遠S/2Sで差し返す）、開幕ジャンプ（畳を飛び越えて着地に空中技）、6P置き（遠Sと5Kに勝つ）。",
        "やめた方がいい開幕：前ダッシュ（畳と5Kに引っかかる）、開幕投げ（5Kで潰される）。"
