        "空中畳（j.236K）：バクステ→空中畳で着地を守る。この時相手は空中で硬直があるので、畳をガードせず『畳が出た位置の外側』から相手の着地にダッシュ近S。畳の真下に入らないこと。",
        "中距離（遠S/5Kが届く距離）：相手の5K（速くて長い）、遠S、2S（姿勢が低い）、5H（遅いが長い）が主力。5Kはこちらの遠Sと同じくらいの距離で振られ、硬直が短いので差し返しにくい。この距離では6Pで遠Sを潰すか、5Kの先端外からダッシュ投げ。",
        "低空妖斬扇（j.236S、低い高度で出す斜め上への斬り）：接近手段の本命。6Pや2Hでの対空に化ける。→ ガードすれば大幅不利で確反。立ちガード（中段）が必要。妖斬扇を警戒して対空技を早めに振ると、相手は着地してから投げに来る。",
        "鉤縛（41236S、引き寄せ）：中距離から当たると引き寄せてコンボ、または追加の派生で続ける。ガード後は不利なので近S確反。中距離で技を空振りした瞬間に差し込まれるので、鉤縛が届く距離で硬直の長い技（5Hなど）を振らない。",
        "緋威（214P、受け流しの構え）：打撃を取られると反撃が確定する。緋威の読み合いは『打撃を振らず、投げる or 何もしない』。構えを見てからダッシュ投げが通る。固めで緋威を出された時は、その後の派生をガードして確反。",
        "接近手段の止め方：低空妖斬扇には立ちガード→確反、前ダッシュには畳の心配がないので2Kや近Sで止める、空ダには6P。ジャンプ攻撃はj.Hが強いが、j.236Sへのキャンセルがあるので対空は早めより『ガードしてから確反』を基本に。",
        "密着：梅喧の近S・2P・2Kは普通で、投げ間合いでの投げも普通。切り返しは覚醒必殺技（連ね三途渡し、632146S）と緋威。密着で固める時は打撃を一度止めて投げを混ぜ、緋威に打撃を取られない。"
