        "連ね三途渡し（632146S）：無敵のある覚醒必殺技で突進。→ ガード後は近Sで確反。起き攻めで相手のテンションが50%以上なら一拍ガードを混ぜる。",
        "拳銖（236236P、大砲）：遠距離からの覚醒必殺技。→ ガード後、近ければダッシュ近Sで確反。遠距離なら反撃できないので前ダッシュで距離を詰める。"
