        "暴れ所：遠Sのガード後は相手がほぼ五分なので2P/5Pで割り込みが通る。畳をガードした後は相手が有利でもなく、次のダッシュ近Sに2Kが噛み合う。鉤縛ガード後は確反なので暴れではなく確反を取る。",
