        "ローリング移動（214S/214H）：本体がヨーヨーの位置まで転がる。ヨーヨーが遠くにある時は瞬間移動に近い。転がりの終わり際に硬直があるので、着地点に近Sや投げを合わせる。ヨーヨーが設置されている時は『相手がどこに移動できるか』を常に意識。",
        "中距離（遠S/5Hの間合い）：遠S（速くて長い）、5H（長い）、2S、6H（非常に長い）、2D（長い下段）が主力。遠Sは硬直が短く差し返しにくいので、6Pで潰すか先端外から前ダッシュ投げ。6Hは遅いので出がかりにジャンプで飛び越える。",
        "キックスタートマイハート（236K、低い突進）：突進して、K追加でシュート（蹴り上げ）、P追加でブレーキ（止まる）。→ しゃがみガードして様子見。ブレーキで止まられると五分前後、そのまま突っ込んできた時やシュートまで出した時はガード後に近S確反。",
        "ロジャーダイブ（ロジャーが上から落ちる技）：空中から降りてくる。起き攻めと中距離の圧に使う。→ 落下点から離れるか、ガードしてから本体を見る。ガード後は相手有利。",
        "接近手段の止め方：ブリジットの接近は低空ダッシュj.S（長い）、前ダッシュ近S、236Kの突進。j.Sは6Pで落とす。ダッシュ近Sは2Kや近Sで止める。236Kはしゃがみガードで受けて確反。",
        "空中戦：j.S、j.H、j.Dが強く、空中での機動が良い。空対空は不利なので地上から6P/2Hで対空する。ヨーヨーが戻ってくる時に飛ぶと戻りに当たるので、ヨーヨーが戻った後に対空の間合いを作る。",
