        "スターシップ（623S）：無敵のある切り返し。空中にも強い。→ ガード後は大幅不利なので近S確反。密着で一拍ガードを混ぜて誘う。",
        "キックスタートマイハート（236K）→シュート（K）/ブレーキ（P）：低い突進。→ しゃがみガード。ブレーキ（止まる）なら反撃しない、そのまま突っ込んできた時やシュートまで出した時は近S確反。",
