        "遠S：長い主力。→ 先端は反撃不可。6Pで潰す。空振りを見てダッシュ近S。",
        "5H / 6H：大きくて遅い。→ 近距離でガードしたら近S確反。出がかりを見たらジャンプで飛び越えるかダッシュで潰す。",
        "2H：対空。→ 2Hの間合いでは飛ばない。空振りを見てダッシュ近S確反。",
