        "相手を壁に追い込んだ時：ベッドマン？の切り返しは覚醒必殺技に頼る。壁際で密着固めをし、遅らせ打撃とダッシュ投げで壁割りまで。相手がテンション50%以上の時はエラー6Eを警戒して一拍ガードを混ぜる。",
