        "5H / 6H：長くて遅い。→ 近距離でガードしたら近S確反。出がかりを見てジャンプで飛び越える。先端は反撃しない。",
        "2D：長い下段。→ しゃがみガード。先端は反撃不可。空振りを見てダッシュ近S。",
        "2H：対空。→ 2Hの間合いでは飛ばない。空振りを見てダッシュ近S確反。",
        "j.S / j.H：空中の主力。→ 6Pで落とす。ガード後の着地に2K/近S。",
        "覚醒必殺技（632146系/236236系）：大きなダメージまたは術の強化。→ 無敵の有無をトレモで確認。ガード後、近ければ近S確反。強化系は発動の硬直にダッシュで触る。"
