        "暴れ所：遠Sガード後は相手がほぼ五分なので2P/5Pで割り込める。術が来ていたら負けるので、暴れは小技で。術をガードした後は相手有利なので暴れない。ブックマークを固めの途中で挟まれたら、その硬直に近S確反。",
        "FDの使い所：近S→遠Sの部分でFDして、術の有効範囲から出る。ビーム系の術はFDするとテンションを消費するので、通常ガードかジャンプで避ける。",
        "バースト：術のヒットで拾い直すコンボ中。本体の5Hや6Hが当たった瞬間を狙う。飛鳥のコンボは術で伸びるので、始動を見たら早めに。",
        "DAA：近S連打の密着固めで、術が来るタイミングではない時。本体の打撃が当たった瞬間。",
        "魔力切れの固め：相手の魔力が無い時の固めは通常技のみ。遠Sガード後の割り込みが通りやすいので、魔力ゲージを見て暴れる。"
