        "優先順位：まずしゃがみガードで術を受け、密着なら4Hで投げ抜け入れ込み。ゴウトゥマーカーで裏に回られる時はマーカーの位置を見てガード方向を切り替え。遅れて発動する術が重なっている時は、発動前に無敵技や暴れをしない。",
