        "相手を壁に追い込んだ時：飛鳥の切り返しは覚醒必殺技に頼る。壁際で密着固めをし、遅らせ打撃とダッシュ投げで壁割りまで。相手がテンション50%以上の時は一拍ガードを混ぜて覚醒必殺技を確反。ゴウトゥマーカーで壁から逃げられるので、マーカーの位置を見て移動先に近Sを合わせる。",
