        "固めの基本ルート（JR）：ダッシュ近S→5H→214K/鍵振り。JR中は有利Fが増え、割り込むとカウンターから半分以上削られる。JR中はガードを優先し、214Kや6Hなど確反の取れる技だけ反撃。",
