        "暴れ所はマッパハンチP/Kガード後、パイルバンカーガード後、5H・6Hガード後。それ以外（近S・遠S・2D・236Sの後）は手を出さない。",
        "近S→遠Sの間に6Pで割り込むと遠Sのカウンターを取れることがあるが、スレイヤーの近S→投げやブラッドサッキングユニバースと択になるので多用しない。",
        "FDは遠Sガード時に使ってマッパPの距離の外へ押し出す。ダンディステップ派生の前にFDすると派生が先端ガードになり反撃が届かなくなるので、ダンディステップ中はFDしない。",
