        "起き上がり優先順位：しゃがみガード＞（密着でステップを見たら）ジャンプ＞投げ抜け仕込み。ブラッドサッキングユニバースは起き上がりジャンプで避けられるが、遅らせ5Hで落とされると半分消える。無敵技は遅らせ5Hに刺さるが、ダンディステップで避けられると最大反撃。",
        "ダンディステップの表裏はステップの距離を見てガード方向を変える。K版は長く裏に回りやすい。迷ったら立ちガードで表（イッツレイトは中段なので立ちガード）。",
