        "ブラッドサッキングユニバース（63214H）空振り → ジャンプで避けた場合は着地近S、バクステで避けた場合は前ダッシュ近S。",
        "5H・6H・2Hガード後 → 近S始動（6Hと5Hの先端はダッシュ近S）。"
