        "相手を壁に追い込んだ時：スレイヤーは無敵技を持たない（覚醒技頼み）が、ダンディステップで攻撃をかわして裏に抜ける。固めの切れ目で2Dや投げを置き、ステップの終わり際に投げを狙う。中段ガトリングを続けると6Pで割り込まれる。",
        "体力リード時：スレイヤーはブラッドサッキングユニバースで体力を回復できるので、こちらの体力リードが小さい時は地上で固まらない。距離を取って相手のマッパハンチ空振りを待ち、確反だけで試合を終わらせる。"
