        "こちらは開幕ジャンプ前進や前ダッシュで距離を詰めるのが基本だが、遠S・6Pの置きに注意。開幕は一度様子見して、バクステを確認したら前ダッシュ。",
        "開幕で飛び道具を撃ってきたら、ガードせず前ジャンプで飛び越えて着地から攻める（魚は地上を進む）。"
