        "FDは飛び道具とミカエルソードのガード時に使う。削りを抑え、距離を離して次の飛び道具を撃つ前に近づけなくするのではなく、通常技が届かない距離にする。",
        "バーストは5H・2Hのカウンターからの浮かせコンボで使う。飛び道具のガード中にバーストする必要は無い。",
